  display: flex;
  flex-wrap: nowrap;
  gap: 0.35rem;
  overflow-x: auto;
  position: sticky;
  top: 0;
  z-index: 10;
  padding: 0.75rem 0;
  margin: 0 0 1.5rem;
  background: var(--background, white);
  scrollbar-width: thin;
}

.alphabet-letter {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-width: 2rem;
  height: 2rem;
  padding: 0 0.4rem;
  border-radius: 0.35rem;
  text-decoration: none;
  font-weight: 600;
}

.alphabet-letter-disabled {
  opacity: 0.3;
  cursor: default;
}

.alphabet-letter:not(.alphabet-letter-disabled):hover {
  background: rgba(127, 127, 127, 0.15);
}

html {
  scroll-behavior: smooth;
}


